{"implementation":"import math

def solve(case):
    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or not is_number(case["threshold"]):
        raise ValueError("threshold must be a finite number")
    if "calls" not in case or not isinstance(case["calls"], list):
        raise ValueError("calls must be a list")

    required = ("call_id", "loss_without_call", "loss_with_call", "prediction_tokens", "parseable")
    validated = []
    for call in case["calls"]:
        if not isinstance(call, dict) or any(field not in call for field in required):
            raise ValueError("invalid call structure")
        if not isinstance(call["call_id"], str):
            raise ValueError("call_id must be a string")
        if not is_number(call["loss_without_call"]) or not is_number(call["loss_with_call"]):
            raise ValueError("losses must be finite numbers")
        if not isinstance(call["prediction_tokens"], int) or isinstance(call["prediction_tokens"], bool) or call["prediction_tokens"] < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(call["parseable"], bool):
            raise ValueError("parseable must be boolean")
        validated.append(call)

    diagnostics = []
    accepted_call_ids = []
    threshold = case["threshold"]
    for call in validated:
        gain = call["loss_without_call"] - call["loss_with_call"]
        normalized = gain / max(1, call["prediction_tokens"])
        rounded = round(normalized, 6)
        if rounded == 0:
            rounded = 0.0
        accepted = call["parseable"] and normalized >= threshold
        diagnostics.append({
            "accepted": accepted,
            "call_id": call["call_id"],
            "normalized_gain": rounded,
        })
        if accepted:
            accepted_call_ids.append(call["call_id"])

    return {"accepted_call_ids": accepted_call_ids, "diagnostics": diagnostics}
